class Solution {
  public long minimumCost(String s, String t, int flipCost, int swapCost, int crossCost) {
    long a = 0, b = 0;
    for (int i = 0; i < s.length(); i++) {
      if (s.charAt(i) == t.charAt(i)) continue;
      if (s.charAt(i) == '0') a++;
      else b++;
    }
    long diffPair = Math.min(swapCost, 2L * flipCost);
    long samePair = Math.min(2L * flipCost, (long) crossCost + swapCost);
    long pairs = Math.min(a, b), rest = Math.abs(a - b);
    return pairs * diffPair + rest / 2 * samePair + rest % 2 * flipCost;
  }
}
